const home = `${heading("Relationship maps for families, cases, history and story worlds", "KinForge Genealogy Studio", "Map how people connect across generations, households, books, cases, campaigns and communities. Built for social workers, writers, genealogists, historians, roleplayers, RPG players and anyone tracking complex relationships.")}<div class="actions"><a class="button" href="/app">Get Started</a><a class="button secondary" href="/downloads">Download</a></div><figure class="product-shot wrap"><img src="/website/chart-desktop.png" width="1440" height="960" alt="KinForge demo relationship tree with connected generations and a person details panel"><figcaption>A fictional family in the separate guest demo. No account required.</figcaption></figure><section class="band"><div class="wrap"><p class="eyebrow">Our mission</p><h2>Know the people. Understand the connections.</h2><p class="lead">KinForge is made for relationship-rich work: family history, social-work genograms, fictional casts, historical networks, tabletop campaigns, RPG worlds and long-running story continuity.</p><p>Use it for family historians, social workers, writers, fantasy and mythology builders, illustrators, roleplayers, DND and RPG players, historians, researchers, and anyone who wants to understand how people, worlds and generations connect.</p><p>Public members create their own KinForge account, then sign in with that account to use their cloud library in the web app, website, and downloaded apps. Special Access users enter their approved private code on the separate Special Access site before using that edition.</p><div class="feature-columns"><article><h3>Across generations</h3><p>Follow parents, partners, siblings, guardians, descendants and other important links in a connected chart.</p></article><article><h3>Across projects</h3><p>Keep books, cases, collections, subcollections, campaigns and trees together in your library.</p></article><article><h3>Beyond names</h3><p>Bring biographies, facts, events, sources, sensitive notes, character notes and case context into one place.</p></article></div><a href="/website/features/">Explore the workspace &rarr;</a></div></section><section class="wrap section"><h2>Start with a person. Open up a network.</h2><p>Try KinForge in a browser or download the Mac and Windows app. Explore the demo, then create a KinForge account for your private cloud library. Once your account exists, you can log in with that same KinForge account across the public web app, website, and downloaded apps.</p><div class="actions left"><a class="button" href="/website/app/">Official app page</a><a class="button secondary" href="/website/tutorials/">Watch tutorials</a></div></section>`;
const officialApp = `${heading("Official KinForge app", "Use KinForge in the browser, on Mac, or on Windows", "This is the official app page for KinForge Genealogy Studio, a product of Dreams of Serene Landscapes for social workers, writers, genealogists, historians, roleplayers, RPG players and more.")}<section class="wrap section prose">${exportTerms}<h2>How to use the app</h2><p><a href="/app">Open the web app</a> for the quickest start, or use the desktop downloads for Mac and Windows. The demo is separate from your signed-in library, so you can try KinForge without putting real work at risk.</p><h2>Who KinForge is for</h2><p>KinForge is for social workers mapping relationships and care context, writers building casts and series continuity, genealogists researching family lines, historians tracking people and evidence, roleplayers and RPG players managing campaigns, and anyone who needs a clear relationship chart with notes, sources and reports.</p><h2>KinForge account sign-in</h2><p>Public members create their own KinForge email-and-password account, then sign in with that account to access their cloud library on the website, web app, Mac app, and Windows app. Accounts do not use ChatGPT login. Store your recovery key safely after creating an account. Special Access users start on the separate Special Access site and enter the approved private code before using that edition.</p><h2>Desktop downloads</h2><p>The current desktop preview includes Apple Silicon Mac, Intel Mac and Windows packages. The download page lists checksums and platform notes.</p><p><a class="button" href="/downloads">Download the official app</a></p><h2>Beta version</h2><p>The beta page is for interest registration only. No payment is collected on this website.</p><p><a href="/website/beta/">Register beta interest</a></p><h2>Tutorials</h2><p>The tutorial page includes captioned walkthrough videos and transcripts for the demo, person profiles, reports and library workflow.</p><p><a href="/website/tutorials/">Open tutorials</a></p></section>`;
const features = `${heading("For social workers, writers, genealogists, historians and players", "A relationship studio with room for real lives and imagined worlds", "Relationships shape care context, evidence, history, motives, loyalties, inheritance, conflict and story continuity. Keep those connections visible as the work grows.")}<section class="wrap section feature-columns"><article><h2>Build a connected network</h2><p>Add earlier and later generations, households, guardians, partners and key relationships. Explore a person's details from the chart.</p></article><article><h2>Organize your worlds or cases</h2><p>Arrange work as Book &rarr; Collection &rarr; Subcollection &rarr; Tree, or use the same structure for cases, research projects, campaigns and archives.</p></article><article><h2>Develop the person</h2><p>Record biographies, appearance, personality, life events, care context, fictional terms, sources and media that support the record.</p></article></section><section class="band"><div class="wrap"><h2>Why relationship mapping matters</h2><p>Genealogy connects people to the generations before and after them. Genograms and relationship maps help social workers and care teams understand context. Historical networks help researchers track evidence and influence. Fiction and RPG trees help creators check ages, explain relationships and keep a long-running cast consistent.</p><p>A connection does not determine a person's character or destiny. Use the tree as context for evidence, care, worldbuilding and choices.</p></div></section><section class="wrap section"><h2>From research to a readable report</h2><p>Explore charts and person, family, kinship and project reports. Keep facts and sources with the people they describe, and export your work for reference.</p><a class="button" href="/website/tutorials/">See the walkthroughs</a></section>`;
